INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','pronouns-and-possessive-determiners','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"pronouns-and-possessive-determiners","title":"Pronouns and possession","level":"A1","order":3,"summary":"Distinguish subjects, objects, possessive determiners and possessive pronouns.","learningGoals":["Subject and object","Before a noun","Replacing a noun phrase"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Subject and object","explanation":"Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form.","examples":["She invited us.","They spoke to me."]},{"title":"Before a noun","explanation":"Use my, your, his, her, its, our or their directly before a noun. These determiners identify the owner.","examples":["Our appointment is tomorrow.","Her parcel has arrived."]},{"title":"Replacing a noun phrase","explanation":"Mine, yours, his, hers, ours and theirs stand on their own. Do not add an apostrophe. His works both before a noun and on its own.","examples":["This seat is yours.","Those gloves are theirs."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Pronouns avoid repeating a noun while keeping clear who or what is being discussed. Their form depends on the job they do in the sentence. English distinguishes subject forms, object forms, possessive determiners before nouns and possessive pronouns that stand alone."],"rules":[{"title":"Subject and object","explanation":"Use I, he, she, we or they as subjects. Use me, him, her, us or them as objects. You and it keep the same form.","examples":["She invited us.","They spoke to me.","**They** invited **us** to **their** house."],"pattern":"**I / he / she / we / they** → subject","paragraphs":["A subject pronoun is the subject of a verb: She called. An object pronoun can be the object of a verb or a preposition: I called her; I spoke to her. In formal standard usage, adding another person does not change the case: Sam and I called, but they called Sam and me."],"id":"pronouns-and-possessive-determiners-foundation-1","domain":"reference","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Before a noun","explanation":"Use my, your, his, her, its, our or their directly before a noun. These determiners identify the owner.","examples":["Our appointment is tomorrow.","Her parcel has arrived.","This notebook is **mine**; the other one is **yours**."],"pattern":"**me / him / her / us / them** → object","paragraphs":["A possessive determiner comes before a noun: my coat, our seats, their plan. A possessive pronoun stands in place of the whole noun phrase: the coat is mine. His has the same form in both jobs, so its position and the following noun reveal its function."],"id":"pronouns-and-possessive-determiners-foundation-2","domain":"reference","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Replacing a noun phrase","explanation":"Mine, yours, his, hers, ours and theirs stand on their own. Do not add an apostrophe. His works both before a noun and on its own.","examples":["This seat is yours.","Those gloves are theirs.","The dog wagged **its** tail because **it’s** happy."],"pattern":"**my book** → **mine** · **their book** → **theirs**","paragraphs":["Possessive pronouns do not take apostrophes: yours, hers, ours, theirs. It’s means it is or it has; its is possessive. You can refer to one or more people, and singular they is commonly used for someone whose gender is unknown or who uses they."],"id":"pronouns-and-possessive-determiners-foundation-3","domain":"reference","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Keep the referent clear when several people are mentioned. If two possible antecedents make she ambiguous, repeat a name. Reflexive pronouns such as herself have a different role: they normally connect an object back to the same subject, or add emphasis.","examples":["**They** invited **us** to **their** house.","This notebook is **mine**; the other one is **yours**.","The dog wagged **its** tail because **it’s** happy."],"id":"pronouns-and-possessive-determiners-foundation-4","domain":"reference","referenceIds":["bc-pronouns","bc-possessives","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"reference","id":"pronoun-reference-and-case","title":"Pronoun case, antecedents and clear reference","explanation":"Subject and object pronoun forms depend on grammatical position, not on politeness or proximity to a name. An antecedent supplies the intended referent, but a pronoun can also refer to the shared situation. In coordination, check each pronoun’s role. Repeating a name can be clearer than leaving two possible antecedents.","pattern":"**She and I** arrived. / They called **her and me**.","examples":["The teacher spoke to **Alex and me**.","When Omar met Luis, **Omar** was carrying the parcel."],"commonMistakes":["Between you and me uses object case after a preposition. Informal It’s me is normal contemporary English; It is I belongs to a more formal register."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"reference","id":"singular-they-generic-reference","title":"Singular they, generic you and indefinite reference","explanation":"They can refer to one person whose gender is unknown, irrelevant or specified that way; the verb still uses the ordinary they form. Generic you refers to people generally, while formal one can do similar work. Indefinite pronouns such as everyone usually take singular agreement but can be referred back to with they.","pattern":"Someone **has** left **their** bag.","examples":["If a visitor arrives, ask whether **they are** expected.","**You** never know what will happen."],"commonMistakes":["Do not switch unpredictably between one, you and they in the same generalisation. Choose a consistent reference pattern and a suitable register."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"reference","id":"dummy-it-and-reference","title":"Referential it, weather it and anticipatory it","explanation":"It can refer to an earlier noun or situation, but it also fills a subject position without naming an object, as in weather, distance and time expressions. Anticipatory it lets a longer clause appear later. Distinguish these uses from demonstrative this or that, which can point to and frame a whole idea.","pattern":"**It** is raining. / **It** is useful to revise.","examples":["**It** is five kilometres to the village.","She lost her ticket. **That** caused a delay."],"commonMistakes":["Weather it does not refer to a hidden person or thing. English usually requires this grammatical subject even when another language omits it."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**I / he / she / we / they** → subject","**me / him / her / us / them** → object","**my book** → **mine** · **their book** → **theirs**"],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["nouns-and-plurals"],"readingReferenceIds":["bc-pronouns","bc-possessives","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='pronouns-and-possessive-determiners'
